using Arconist.Core;
using Arconist.Bridge;
using Arconist.Records;
using System.Text.Json;
using System.Text.Json.Nodes;
using System.Diagnostics;
using System.Security.Cryptography;
sealed class Clock:IMonotonicClock{public long Milliseconds{get;set;}}
static class Program
{
 static string root="",output="";static int passed,failed,ordinal;
 static readonly List<object> outcomes=new(),ledger=new();
 static void C(bool ok,string why){if(!ok)throw new Exception(why);}
 static void T(string name,Action body){try{body();passed++;outcomes.Add(new{name,status="PASS"});Console.WriteLine("PASS "+name);}catch(Exception e){failed++;outcomes.Add(new{name,status="FAIL",error=e.ToString()});Console.WriteLine("FAIL "+name+": "+e.Message);}}
 static string Aff(string file="ordinary_two_tap.aff")=>File.ReadAllText(Path.Combine(root,"reconstructed/godot/content",file));
 static ChartIdentity Identity(string file="ordinary_two_tap.aff")=>BundledCatalog.Find(file).Identity(Aff(file));
 static string NewPath()=>RecordPaths.ForUserData(Path.Combine(output,"case"+(++ordinal)));
 static SavedResult Prepared(int score,int category,long date)=>new(score,10,10,category==3?0:1,category is 2 or 3?0:1,99,category==0?-1:80,category,10,0,0,date,unchecked((int)date),1,0);
 static string Hash(string file)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(file)));
 static (GameplaySession,SessionRecords,Clock) Start(LocalRecordStore store)
 {var clock=new Clock();var s=new GameplaySession(clock);var records=new SessionRecords(s,store,()=>DateTimeOffset.FromUnixTimeSeconds(1700000000));records.Start("ordinary_two_tap.aff",Aff());clock.Milliseconds=3002;s.Frame();return(s,records,clock);}
 static void Complete(GameplaySession s,Clock c,bool hit=true)
 {foreach(var item in new[]{(1000,'J'),(2000,'F')}){c.Milliseconds=item.Item1+3002;s.Frame();if(hit){s.Key(item.Item2,true);s.Key(item.Item2,false);}}c.Milliseconds=5123;s.Frame();}
 static string Child(bool write,string directory)
 {
  var info=new ProcessStartInfo(Path.Combine(Environment.GetEnvironmentVariable("DOTNET_ROOT")!,"dotnet")){RedirectStandardOutput=true,RedirectStandardError=true};
  foreach(string a in new[]{typeof(Program).Assembly.Location,write?"--process-write":"--process-read",root,directory})info.ArgumentList.Add(a);
  using var p=Process.Start(info)!;string stdout=p.StandardOutput.ReadToEnd(),stderr=p.StandardError.ReadToEnd();C(p.WaitForExit(15000)&&p.ExitCode==0,"child process: "+stdout+stderr);return stdout.Trim();
 }
 static int ProcessProbe(string[] args)
 {
  root=Path.GetFullPath(args[1]);string path=RecordPaths.ForUserData(args[2]);using var store=new LocalRecordStore(path);C(!store.HasError,store.Detail);
  if(args[0]=="--process-write"){C(store.Count==0,"fresh process store");var(s,rec,c)=Start(store);using(rec){Complete(s,c);C(s.Core!.Result!.Score==10000002&&rec.LastOutcome?.Written==true,"ordinary completion writes actual backend");s.Home();}}
  else C(store.LoadedFromDisk&&store.Get(Identity())?.BestScore.Score==10000002&&store.SuccessfulWrites==0,"fresh process reload");
  var row=store.Get(Identity())!;C(row.BestScore.Health==80&&row.BestScore.Lost==0&&row.BestScore.RecordedLost==0&&row.ClearType==3,"native-informed snapshot");Console.WriteLine(JsonSerializer.Serialize(new{hash=Hash(path),score=row.BestScore.Score,clear=row.ClearType,path}));return 0;
 }
 public static int Main(string[] args)
 {
  if(args[0].StartsWith("--process-",StringComparison.Ordinal))return ProcessProbe(args);
  root=Path.GetFullPath(args[0]);output=Path.GetFullPath(args[1]);Directory.CreateDirectory(output);
  var oracle=JsonDocument.Parse(File.ReadAllText(Path.Combine(root,"reconstructed/campaigns/S01-normal-gameplay/w2-03/E013-oracles.json"))).RootElement;
  foreach(var row in oracle.GetProperty("clearComparator").EnumerateArray())
  {int old=row.GetProperty("stored").GetInt32(),incoming=row.GetProperty("incoming").GetInt32();bool expected=row.GetProperty("accept").GetBoolean();T($"E013 clear old{old} new{incoming}",()=>C(RecordRules.ImprovesClear(incoming,old)==expected,"frozen native truth table"));}
  T("all26 stable synthetic identity/profile/content mappings",()=>{C(BundledCatalog.Entries.Count==26,"26 choices");var keys=new HashSet<string>();foreach(var c in BundledCatalog.Entries){var id=c.Identity(Aff(c.File));C(id.ContentSha256==c.PackagedSha256&&id.Profile==c.Profile.ToString()&&id.Difficulty==0&&!id.Ct&&keys.Add(id.Key),"catalog identity "+c.File);C(c.Identity(Aff(c.File))==id,"stable across new instance");}C(BundledCatalog.Entries.Count(c=>c.Profile==ChartProfile.S01Mixed)==8,"unchanged profiles");});
  T("native strict score and independent clear sequence retains attached dates",()=>{using var store=new LocalRecordStore(NewPath());var id=Identity();foreach(var row in oracle.GetProperty("scoreSequence").EnumerateArray()){int score=row.GetProperty("score").GetInt32(),category=row.GetProperty("category").GetInt32();long date=row.GetProperty("date").GetInt64();var result=store.Record(id,Prepared(score,category,date));C(result.Success,store.Detail);var saved=store.Get(id)!;C(saved.BestScore.Score==row.GetProperty("best").GetInt32()&&saved.BestScore.UtcUnixSeconds==row.GetProperty("bestDate").GetInt64()&&saved.ClearType==row.GetProperty("clear").GetInt32(),"E013 stored values");C(saved.BestScore==Prepared(row.GetProperty("best").GetInt32(),1,row.GetProperty("bestDate").GetInt64()),"entire native-sequence best snapshot retained");ledger.Add(new{score,category,date,result,saved});}C(store.SuccessfulWrites==5,"all five sequence transitions change one independent record component");});
  T("all42 relations drive actual disk backend independently of score",()=>{foreach(var row in oracle.GetProperty("clearComparator").EnumerateArray()){using var store=new LocalRecordStore(NewPath());int old=row.GetProperty("stored").GetInt32(),incoming=row.GetProperty("incoming").GetInt32();var id=Identity();if(old>=0)C(store.Record(id,Prepared(1000,old,100)).Success,"seed");var result=store.Record(id,Prepared(900,incoming,101));var saved=store.Get(id)!;bool accept=row.GetProperty("accept").GetBoolean();C(result.Success&&saved.ClearType==(accept?incoming:old)&&saved.BestScore.Score==(old<0?900:1000),"actual native relation / separate score");}});
  T("equal lower unchanged score retains every snapshot field and exact bytes",()=>{using var store=new LocalRecordStore(NewPath());var id=Identity();var first=Prepared(9200000,3,100);store.Record(id,first);string bytes=Hash(store.FilePath);foreach(var next in new[]{Prepared(9200000,1,101),Prepared(8900000,0,102)}){var r=store.Record(id,next);C(r.Success&&!r.Written&&store.Get(id)!.BestScore==first&&Hash(store.FilePath)==bytes,"strict comparison preserves fields/date/bytes");}C(store.SuccessfulWrites==1,"unchanged is not written");});
  T("invalid stored clear normalizes missing without discarding best score",()=>{string path=NewPath();var id=Identity();using(var s=new LocalRecordStore(path))s.Record(id,Prepared(9000000,1,100));var json=JsonNode.Parse(File.ReadAllText(path))!;json["records"]![0]!["clearType"]=99;File.WriteAllText(path,json.ToJsonString());using var store=new LocalRecordStore(path);C(!store.HasError&&store.Get(id)!.NormalizedClear==-1,"original invalid normalization");var r=store.Record(id,Prepared(8000000,0,101));C(r.ClearChanged&&!r.ScoreChanged&&store.Get(id)!.ClearType==0&&store.Get(id)!.BestScore.UtcUnixSeconds==100,"invalid is missing, separate preserved score");foreach(int bad in new[]{-99,-2,6,99})C(RecordRules.NormalizeClear(bad)==-1,"native normalization");});
  T("identity partitions isolate chart content profile and fixed metadata",()=>{using var store=new LocalRecordStore(NewPath());ChartIdentity a=Identity(),b=Identity("native_widen_camera.aff"),changed=ChartIdentity.FromAff(a.ChartId,ChartProfile.R010,Aff()+"\n"),profile=ChartIdentity.FromAff(a.ChartId,ChartProfile.S01Mixed,Aff());foreach(var id in new[]{a,b,changed,profile})C(store.Record(id,Prepared(1000,1,100)).Success,"separate key");C(store.Count==4&&new[]{a,b,changed,profile}.Select(x=>x.Key).Distinct().Count()==4,"no cross-talk");C(store.Get(a)!.BestScore.Modifier==0&&!a.Ct&&a.Difficulty==0,"modifier is not ct; fixed synthetic metadata");store.Record(a,Prepared(2000,3,101));C(store.Get(b)!.BestScore.Score==1000&&store.Get(changed)!.ClearType==1,"other identities unchanged");});
  T("new store instance reloads immutable fields from actual production path",()=>{string path=NewPath();var id=Identity();var result=Prepared(9000000,1,100);using(var a=new LocalRecordStore(path))C(a.Record(id,result).Success,"write");using var b=new LocalRecordStore(path);C(b.LoadedFromDisk&&!b.HasError&&b.Get(id)!.BestScore==result&&path.EndsWith("records/best-records.v1.json",StringComparison.Ordinal),"disk reload");});
  T("corrupt truncated and incompatible stores block every later overwrite",()=>{foreach(string content in new[]{"{", "{\"schemaVersion\":2,\"records\":[]}","{\"schemaVersion\":1}","{\"schemaVersion\":1,\"records\":[],\"unknown\":1}"}){string path=NewPath();Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,content);string before=Hash(path);using var store=new LocalRecordStore(path);C(store.HasError,"explicit parse/schema failure");C(!store.Record(Identity(),Prepared(9000000,3,100)).Success&&Hash(path)==before&&store.SuccessfulWrites==0,"preserve unreadable store");}});
  T("write failure preserves previous file and in-memory best",()=>{string path=NewPath();using var store=new LocalRecordStore(path);var id=Identity();store.Record(id,Prepared(9000000,1,100));string bytes=Hash(path);Directory.CreateDirectory(store.BackupPath);var r=store.Record(id,Prepared(9200000,3,101));C(!r.Success&&store.HasError&&Hash(path)==bytes&&store.Get(id)!.BestScore.Score==9000000&&store.SuccessfulWrites==1,"real File.Replace failure cannot fabricate success");C(!store.Record(id,Prepared(9300000,3,102)).Success&&Hash(path)==bytes,"blocked until recovery");});
  T("exclusive store ownership prevents a second simultaneous writer",()=>{string path=NewPath();using var first=new LocalRecordStore(path);using var second=new LocalRecordStore(path);C(!first.HasError&&second.HasError&&!second.Record(Identity(),Prepared(10,1,100)).Success,"single-process ownership");C(first.Record(Identity(),Prepared(9000000,3,100)).Success,"first remains healthy");});
  T("external file mutation is detected rather than silently replaced",()=>{string path=NewPath();using var store=new LocalRecordStore(path);store.Record(Identity(),Prepared(9000000,1,100));File.WriteAllText(path,"external truncated bytes");string before=Hash(path);C(!store.Record(Identity(),Prepared(9200000,3,101)).Success&&store.HasError&&Hash(path)==before,"external corruption protection");});
  T("natural completion captures existing immutable GameResult once",()=>{using var store=new LocalRecordStore(NewPath());var(s,rec,c)=Start(store);using(rec){Complete(s,c);var r=s.Core!.Result!;var saved=store.Get(Identity())!;C(r.Score==10000002&&r.Health==80&&r.Category==3&&r.Lost==0&&saved.BestScore==SavedResult.Capture(r,DateTimeOffset.FromUnixTimeSeconds(1700000000)),"native two-tap result/copy");for(int i=0;i<100;i++)s.Frame();C(rec.CompletionAttempts==1&&store.WriteAttempts==1&&store.SuccessfulWrites==1&&rec.LastOutcome?.Written==true,"once-only completion");s.Home();C(store.SuccessfulWrites==1,"menu no new save");}});
  T("start pause focus early home and retry cannot save incomplete results",()=>{using var store=new LocalRecordStore(NewPath());var(s,rec,c)=Start(store);using(rec){c.Milliseconds=4002;s.Frame();s.Key('J',true);s.Pause();c.Milliseconds+=60000;s.Frame();s.FocusLost();s.FocusReturned();s.Home();rec.Start("ordinary_two_tap.aff",Aff());s.Home();C(rec.CompletionAttempts==0&&store.WriteAttempts==0&&store.SuccessfulWrites==0&&!File.Exists(store.FilePath),"all incomplete lifecycle routes");}});
  T("ordinary completed category0 is eligible and gets a first record",()=>{using var store=new LocalRecordStore(NewPath());var(s,rec,c)=Start(store);using(rec){Complete(s,c,false);C(s.Core!.Result!.Category==0&&rec.LastOutcome?.Written==true&&store.Get(Identity())!.ClearType==0&&store.Get(Identity())!.BestScore.Lost==2,"failure is not an early quit");}});
  T("storage error cannot change gameplay judgments or result",()=>{string path=NewPath();Directory.CreateDirectory(Path.GetDirectoryName(path)!);File.WriteAllText(path,"broken");using var store=new LocalRecordStore(path);var(s,rec,c)=Start(store);using(rec){Complete(s,c);C(s.Core!.Result!.Score==10000002&&s.Core.Result.Health==80&&s.Core.Pure==2&&rec.LastOutcome?.Success==false&&File.ReadAllText(path)=="broken","game remains playable and error explicit");}});
  T("final LOST and native low32 date remain distinct explicit fields",()=>{using var store=new LocalRecordStore(NewPath());var row=Prepared(9000000,1,2147483648);C(store.Record(Identity(),row).Success,"field capture");var saved=store.Get(Identity())!.BestScore;C(saved.Lost==1&&saved.RecordedLost==99&&saved.NativeDate32==int.MinValue&&saved.UtcUnixSeconds==2147483648&&saved.Health==80,"E013 writer field provenance");});
  T("separate real child processes write and reload identical persisted bytes",()=>{string directory=Path.Combine(output,"cross-process");var write=JsonDocument.Parse(Child(true,directory)).RootElement.Clone();var read=JsonDocument.Parse(Child(false,directory)).RootElement.Clone();C(write.GetProperty("hash").GetString()==read.GetProperty("hash").GetString()&&read.GetProperty("score").GetInt32()==10000002&&read.GetProperty("clear").GetInt32()==3,"actual process restart");ledger.Add(new{processWrite=write,processRead=read});});
  File.WriteAllText(Path.Combine(output,"record-tests.json"),JsonSerializer.Serialize(new{passed,failed,skipped=0,outcomes,ledger,independent="NOT RUN",ownerWindows="PENDING"},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"W2-03 records: {passed+failed}; passed:{passed}; failed:{failed}; skipped:0");return failed==0?0:1;
 }
}
